+/* -------------------------------------------------------------------------------- rails */
+
+const RAIL_COLLECTION_MODES: Record<string, string> = {
+  REDIRECT: "REDIRECT",
+  EMBEDDED: "EMBEDDED",
+  QR: "QR_DISPLAY",
+  PUSH: "PUSH_APPROVAL",
+  TRANSFER: "MANUAL",
