+  const result: JsonRecord = {
+    code: (asString(source.code) ?? "").trim().toLowerCase(),
+    nameAr: name,
+    nameEn: name,
+    collectionMode: toCoreCollectionMode(source.collectionMode) ?? missingCanonical("collectionMode"),
