 map $http_upgrade $connection_upgrade {
     default upgrade;
     ''      close;
 }

 limit_req_zone $binary_remote_addr zone=api_per_ip:10m rate=20r/s;
 limit_conn_zone $binary_remote_addr zone=per_ip_connections:10m;

 upstream merchant_back {
     server 127.0.0.1:4102;
     keepalive 32;
 }

 upstream checkout_back {
     server 127.0.0.1:4103;
     keepalive 32;
 }

 server {
     listen 80;
     listen [::]:80;
     server_name merchant.domain.ly pay.domain.ly;

     location /.well-known/acme-challenge/ {
         root /var/www/acme;
     }

     location / {
         return 308 https://$host$request_uri;
     }
 }

